    def test_record_review_transitions_status(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            self.assertEqual(0, main(["--root", str(root), "init", "--phase", "phase-01"]))
            phase_dir = root / "phase-01"
            (root / "file.py").write_text("source", encoding="utf-8")
            review = root / "review.md"
            review_text = "PASS"
            request_text = "review this"
            bundle_text = "bundle bytes"
            review.write_text(review_text, encoding="utf-8")
            review_request = root / "request.md"
            review_request.write_text(request_text, encoding="utf-8")
            review_bundle = root / "bundle.zip"
            review_bundle.write_text(bundle_text, encoding="utf-8")
            invocation_receipt = root / "receipt.json"
            (phase_dir / "evidence.txt").write_text("proof", encoding="utf-8")
            status_file = status_path(root, "phase-01")
            status = load_status(status_file)
            status.update(
                {
                    "acceptance_contract": ["contract"],
                    "changed_files": [{"path": "file.py", "sha256": sha256_text("source")}],
                    "validation_commands": [{"command": "true", "exit_code": 0}],
                    "evidence_artifacts": ["evidence.txt"],
                }
            )
            add_skill_context(phase_dir, status)
            save_status(status_file, status)
            skill_context_sha256 = compute_skill_context_sha256(status, phase_dir)
            invocation_receipt.write_text(
                receipt_for(
                    review_text,
                    request_text,
                    bundle_text,
                    phase_subject_sha256=compute_phase_subject_sha256(status),
                    skill_context_sha256=skill_context_sha256,
                ),
                encoding="utf-8",
            )

            exit_code = main(
                [
                    "--root",
                    str(root),
                    "record-review",
                    "--phase",
                    "phase-01",
                    "--verdict",
                    "passed",
                    "--review",
                    str(review),
                    "--review-request",
                    str(review_request),
                    "--review-bundle",
                    str(review_bundle),
                    "--invocation-command",
                    "curl /v1/chat/completions model=gpt-5.5 reasoning_effort=high",
                    "--invocation-receipt",
                    str(invocation_receipt),
                    "--repo-root",
                    str(root),
                ]
            )

            self.assertEqual(0, exit_code)
            updated = load_status(status_file)
            self.assertEqual("external_review_passed", updated["status"])
            self.assertEqual("passed", updated["review_status"])
            self.assertEqual("scillm", updated["review_results"][0]["adjudicator_kind"])
            self.assertIn("artifact_sha256", updated["review_results"][0])
            self.assertIn("review_request_sha256", updated["review_results"][0])
            self.assertIn("review_bundle_sha256", updated["review_results"][0])
            self.assertIn("receipt_sha256", updated["review_results"][0]["invocation"])
            self.assertTrue((phase_dir / updated["review_results"][0]["review_request_artifact"]).exists())
            self.assertTrue((phase_dir / updated["review_results"][0]["review_bundle_artifact"]).exists())
            self.assertTrue((phase_dir / updated["review_results"][0]["invocation"]["receipt_artifact"]).exists())
            self.assertTrue(updated["review_comparison"]["closure_allowed"])
            self.assertTrue(any((phase_dir / artifact).exists() for artifact in updated["review_artifacts"]))

