    def test_comparison_required_records_reviews_then_comparison(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            self.assertEqual(0, main(["--root", str(root), "init", "--phase", "phase-01"]))
            phase_dir = root / "phase-01"
            (root / "file.py").write_text("source", encoding="utf-8")
            (phase_dir / "evidence.txt").write_text("proof", encoding="utf-8")
            progress_context_text = "Prior findings: none yet.\nCurrent delta: initial comparison review.\n"
            (phase_dir / "progress-context.md").write_text(
                progress_context_text,
                encoding="utf-8",
            )
            status_file = status_path(root, "phase-01")
            status = load_status(status_file)
            status.update(
                {
                    "status": "ready_for_review",
                    "acceptance_contract": ["contract"],
                    "changed_files": [{"path": "file.py", "sha256": sha256_text("source")}],
                    "validation_commands": [{"command": "true", "exit_code": 0}],
                    "evidence_artifacts": ["evidence.txt"],
                    "progress_context_artifacts": [
                        {"path": "progress-context.md", "sha256": sha256_text(progress_context_text)}
                    ],
                    "memory_context": {
                        "collection": "plan_iterate_phase_context",
                        "keys": ["phase-01-initial-comparison"],
                    },
                    "reviewer_policy": {
                        "required": True,
                        "comparison_required": True,
                        "closure_rule": "deterministic_validation_and_external_review",
                    },
                }
            )
            add_skill_context(phase_dir, status)
            save_status(status_file, status)
            phase_subject_sha256 = compute_phase_subject_sha256(status)
            progress_context_sha256 = compute_progress_context_sha256(status, phase_dir)
            skill_context_sha256 = compute_skill_context_sha256(status, phase_dir)
            shared_bundle_text = "same bundle bytes"

            for reviewer, adjudicator in [("webgpt", "webgpt"), ("scillm-gpt55", "scillm")]:
                review_text = f"PASS {reviewer}"
                request_text = f"review this {reviewer}"
                bundle_text = shared_bundle_text
                review = root / f"{reviewer}-review.md"
                request = root / f"{reviewer}-request.md"
                bundle = root / f"{reviewer}-bundle.zip"
                receipt = root / f"{reviewer}-receipt.json"
                review.write_text(review_text, encoding="utf-8")
                request.write_text(request_text, encoding="utf-8")
                bundle.write_text(bundle_text, encoding="utf-8")
                receipt.write_text(
                    receipt_for(
                        review_text,
                        request_text,
                        bundle_text,
                        reviewer,
                        adjudicator,
                        phase_subject_sha256,
                        progress_context_sha256,
                        skill_context_sha256,
                    ),
                    encoding="utf-8",
                )
                self.assertEqual(
                    0,
                    main(
                        [
                            "--root",
                            str(root),
                            "record-review",
                            "--phase",
                            "phase-01",
                            "--verdict",
                            "passed",
                            "--review",
                            str(review),
                            "--review-request",
                            str(request),
                            "--review-bundle",
                            str(bundle),
                            "--invocation-command",
                            f"{adjudicator} review",
                            "--invocation-receipt",
                            str(receipt),
                            "--reviewer",
                            reviewer,
                            "--adjudicator-kind",
                            adjudicator,
                            "--repo-root",
                            str(root),
                        ]
                    ),
                )

            mid_status = load_status(status_file)
            self.assertEqual("ready_for_review", mid_status["status"])
            self.assertEqual(
                0,
                main(
                    [
                        "--root",
                        str(root),
                        "record-comparison",
                        "--phase",
                        "phase-01",
                        "--agreement",
                        "agree",
                        "--closure-allowed",
                        "--reason",
                        "two reviewers passed",
                        "--repo-root",
                        str(root),
                    ]
                ),
            )
            updated = load_status(status_file)
            self.assertEqual("external_review_passed", updated["status"])


